/// <summary>
/// UPSPricingAttribute of table <c>MCRCustCategory</c> field Level.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeMCRCustCategoryLevel extends UPSPricingAttributeMCRCustCategory implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(MCRCustCategory, Level);
}

public Set getAllowedValues()
{
    var             ret = new Set(Types::Int64);
    MCRCustCategory mCRCustCategory;

    while select mCRCustCategory
        group by Level
    {
        if (! ret.in(mCRCustCategory.Level))
        {
            ret.add(mCRCustCategory.Level);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRCustCategory, Level));
    qbr.value(queryValue(_value));
}
